package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, offset 0. '000123 ' has space at end.
        // end becomes 6, then 5. Loop processes 000123
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(83L, result); // 123 octal is 83 decimal
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   755 ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(493L, result); // 755 octal is 493 decimal
    }

    @Test
    public void testParseOctal_ValidWithNULTrailer() {
        byte[] buffer = "000010\0\0".getBytes();
        // length 7. buffer[6] is \0. end becomes 6. buffer[5] is 0. end becomes 5.
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(8L, result);
    }

    @Test
    public void testParseOctal_ValidWithSpaceAndNUL() {
        byte[] buffer = " 007 \0".getBytes();
        // length 6. buffer[5] is \0. end becomes 5. buffer[4] is ' '. end becomes 4.
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(7L, result);
    }

    @Test
    public void testParseOctal_ZeroBufferStart() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_TooShortLength() {
        byte[] buffer = "1".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidTrailer() {
        byte[] buffer = "000123X".getBytes();
        TarUtils.parseOctal(buffer, 0, 7);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "000800 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 7);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigitAlpha() {
        byte[] buffer = "000A00 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 7);
    }

    @Test
    public void testParseOctal_OffsetTesting() {
        byte[] buffer = "junk 0123  ".getBytes();
        // junk is 4 bytes. offset 4. length 7. "0123  "
        // end = 11. buffer[10] is ' '. end=10. buffer[9] is ' '. end=9.
        // start = 4. loop 4 to 9.
        long result = TarUtils.parseOctal(buffer, 4, 7);
        assertEquals(10L, result); // 12 octal is 10 decimal
    }

    @Test
    public void testParseOctal_LargeValue() {
        // Max octal for long might be large, let's test a known one
        // 777777777777 (octal)
        byte[] buffer = "777777777777 ".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, buffer.length);
        // 777777777777 octal = 549755813887 decimal
        assertEquals(549755813887L, result);
    }
}
